#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
	int t;
	cin>>t;
	
	while(t--){
	    int n;
	    cin>>n;
	    
	    vector<long long> a(3*n);
	    
	    for(int i=0;i<3*n;i++){
	        cin>>a[i];
	    }
	    
	    sort(a.rbegin(),a.rend());
	    
	    vector<long long> pref(3*n+1,0);
	    
	    for(int i=0;i<3*n;i++){
	        pref[i+1]=pref[i]+a[i];
	    }
	    
	    long long ans=0;
	    
	    
	    for(int A=0;A<=n;A++){
	        int lo=0;
	        int hi=n-A;
	        
	        while(lo<hi){
	            int B=(lo+hi)/2;
	            
	            int q=A+2*B;
	            int r=3*n-2*A-B;
	            
	            long long change=a[q]+a[q+1]-3*a[r-1];
	            
	            if(change>=0){
	                lo=B+1;
	            }
	            else{
	                hi=B;
	            }
	        }
	            
	            for(int B:{lo,max(0,lo-1)}){
	                if(B>n-A){
	                    continue;
	                }
	                
	                int C=n-A-B;
	                
	                int q=A+2*B;
	                int r=q+3*C;
	                
	                long long cur=6LL*pref[A]+ 4LL*(pref[q]-pref[A])+3LL*(pref[r]-pref[q]);
	                
	                ans=max(ans,cur);
	            }
	        }
	        
	        cout<<ans<<endl;
	    }
	    
	    return 0;
	

}
